package com.alpharip.staffmod.BuildTimelapse.export; import java.util.concurrent.*; public final class ExportQueue {private final ExecutorService executor=Executors.newSingleThreadExecutor();private volatile boolean busy;public synchronized Future<?> submit(final VideoEncoder e,final ExportJob j){if(busy)throw new IllegalStateException("Export busy");busy=true;return executor.submit(new Runnable(){public void run(){try{e.encode(j);}catch(Exception x){throw new RuntimeException(x);}finally{busy=false;}}});}public boolean isBusy(){return busy;}public void shutdown(){executor.shutdown();}}
